from queueing import payload

def submit(owner, enqueue, batch_size=20):
    if not isinstance(batch_size, int) or batch_size < 1 or batch_size > 100:
        raise ValueError('batch_size must be integer 1..100')
    return enqueue(payload(owner, batch_size))

def execute(task, process):
    # task may have batch_size from payload; fallback 20
    batch = task.get('batch_size', 20)
    if not isinstance(batch, int) or batch < 1 or batch > 100:
        # already validated on submit, but fallback safe
        batch = 20
    return process(task['owner'], batch)

